<?php
declare(strict_types=1); require __DIR__.'/../config/auth.php'; require __DIR__.'/../config/database.php'; require __DIR__.'/../config/platform_settings.php'; require __DIR__.'/../config/chat_topics.php'; require __DIR__.'/../config/audit.php';function audit_saved_setting(string $key, mixed $new): void {$old=platform_setting($key,null);$a=json_encode($old,JSON_UNESCAPED_UNICODE);$b=json_encode($new,JSON_UNESCAPED_UNICODE);if($a!==$b)audit_log('platform.setting_change','platform_settings',null,['key'=>$key,'old'=>$old,'new'=>$new]);} require_admin(); if(empty($_SESSION['admin_csrf']))$_SESSION['admin_csrf']=bin2hex(random_bytes(32));$message='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['admin_csrf'],(string)($_POST['csrf']??'')))$error='Güvenlik doğrulaması geçersiz.';elseif(($_POST['digest_remove']??'')!==''){$parts=explode(':',(string)$_POST['digest_remove'],2);$digest=(array)platform_setting('panel_weekly_digest',[]);if(isset($parts[1])&&in_array($parts[0],['supplier','agency'],true)){$digestOld=$digest;unset($digest[$parts[0]][$parts[1]]);save_platform_setting('panel_weekly_digest',$digest);audit_log('platform.setting_change','platform_settings',null,['key'=>'panel_weekly_digest','old'=>$digestOld,'new'=>$digest]);$message='Katılımcı haftalık özetten çıkarıldı.';}else{$error='Katılımcı kaldırma isteği geçersiz.';}}else{$threshold=(int)($_POST['gemini_visual_similarity_threshold']??90);$email=trim((string)($_POST['admin_alert_email']??''));if($threshold<50||$threshold>100)$error='Görsel benzerlik eşiği 50 ile 100 arasında olmalıdır.';elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Uyarı e-posta adresi geçerli değil.';else{save_platform_setting('gemini_visual_similarity_threshold',$threshold);audit_saved_setting('gemini_visual_similarity_threshold',$threshold);save_platform_setting('gemini_auto_pause_duplicate',isset($_POST['gemini_auto_pause_duplicate']));audit_saved_setting('gemini_auto_pause_duplicate',isset($_POST['gemini_auto_pause_duplicate']));save_platform_setting('kps_identity_verification_enabled',isset($_POST['kps_identity_verification_enabled']));audit_saved_setting('kps_identity_verification_enabled',isset($_POST['kps_identity_verification_enabled']));save_platform_setting('admin_alert_email',$email);audit_saved_setting('admin_alert_email',$email);$blocklistRaw=(string)($_POST['chat_blocklist']??'');$blocklist=array_values(array_filter(array_map('trim',preg_split('/\r\n|\r|\n/',$blocklistRaw)),fn($l)=>$l!==''));save_platform_setting('chat_blocklist',$blocklist);audit_saved_setting('chat_blocklist',$blocklist);$minLenRaw=(int)($_POST['chat_min_length']??5);$minLenRaw=max(1,min(100,$minLenRaw));save_platform_setting('chat_min_length',$minLenRaw);audit_saved_setting('chat_min_length',$minLenRaw);save_platform_setting('chat_require_space',isset($_POST['chat_require_space']));audit_saved_setting('chat_require_space',isset($_POST['chat_require_space']));save_platform_setting('chat_topic_instant',isset($_POST['chat_topic_instant']));audit_saved_setting('chat_topic_instant',isset($_POST['chat_topic_instant']));$topicRaw=(array)($_POST['chat_topic_responses']??[]);$topicSaved=[];foreach(array_keys(chat_topic_defs()) as $t){$text=trim((string)($topicRaw[$t]['text']??''));$link=trim((string)($topicRaw[$t]['link']??''));if($text===''&&$link==='')continue;$topicSaved[$t]=['text'=>mb_substr($text,0,500),'link'=>mb_substr($link,0,190)];}save_platform_setting('chat_topic_responses',$topicSaved);audit_saved_setting('chat_topic_responses',$topicSaved);save_platform_setting('ical_url_published_only',isset($_POST['ical_url_published_only']));audit_saved_setting('ical_url_published_only',isset($_POST['ical_url_published_only']));$webhookCurrency=strtoupper(trim((string)($_POST['channel_webhook_default_currency']??'EUR')));if(!preg_match('/^[A-Z]{3}$/',$webhookCurrency))$webhookCurrency='EUR';save_platform_setting('channel_webhook_default_currency',$webhookCurrency);audit_saved_setting('channel_webhook_default_currency',$webhookCurrency);save_platform_setting('channel_webhook_auto_map',isset($_POST['channel_webhook_auto_map']));audit_saved_setting('channel_webhook_auto_map',isset($_POST['channel_webhook_auto_map']));$webhookLoopThreshold=max(3,min(100,(int)($_POST['channel_webhook_loop_threshold']??3)));save_platform_setting('channel_webhook_loop_threshold',$webhookLoopThreshold);audit_saved_setting('channel_webhook_loop_threshold',$webhookLoopThreshold);$icalRepeatThreshold=max(3,min(100,(int)($_POST['ical_repeat_threshold']??3)));save_platform_setting('ical_repeat_threshold',$icalRepeatThreshold);audit_saved_setting('ical_repeat_threshold',$icalRepeatThreshold);$webhookMaxRetries=max(2,min(10,(int)($_POST['channel_webhook_max_retries']??3)));save_platform_setting('channel_webhook_max_retries',$webhookMaxRetries);audit_saved_setting('channel_webhook_max_retries',$webhookMaxRetries);$trashTtl=max(7,min(365,(int)($_POST['feature_trash_ttl_days']??30)));save_platform_setting('feature_trash_ttl_days',$trashTtl);audit_saved_setting('feature_trash_ttl_days',$trashTtl);save_platform_setting('readiness_all_auto_open',isset($_POST['readiness_all_auto_open']));audit_saved_setting('readiness_all_auto_open',isset($_POST['readiness_all_auto_open']));$readinessThreshold=max(1,min(100,(int)($_POST['readiness_all_auto_open_threshold']??70)));save_platform_setting('readiness_all_auto_open_threshold',$readinessThreshold);audit_saved_setting('readiness_all_auto_open_threshold',$readinessThreshold);$message='Kontrol merkezi ayarları veritabanına kaydedildi.';}}}$threshold=(int)platform_setting('gemini_visual_similarity_threshold',90);$autoPause=(bool)platform_setting('gemini_auto_pause_duplicate',true);$kpsEnabled=(bool)platform_setting('kps_identity_verification_enabled',false);$email=(string)platform_setting('admin_alert_email','');$icalPublishedOnly=(bool)platform_setting('ical_url_published_only',false);?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kontrol merkezi | NEXUS Admin</title><style>body{margin:0;background:#f7f7f2;color:#10211f;font-family:Arial}.wrap{width:min(850px,calc(100% - 32px));margin:40px auto}.card{background:#fff;border:1px solid #e1e5de;padding:24px;margin-top:20px}.form{display:grid;gap:15px}.form input{padding:11px;border:1px solid #d8ded8;font:inherit}.form button{border:0;background:#10211f;color:#fff;padding:12px;font-weight:bold}.toggle{display:flex;gap:10px;align-items:center}.muted{color:#64716d;line-height:1.5}.notice{background:#e6f8c7;padding:10px}.error{background:#ffe2de;padding:10px}.links{display:flex;gap:10px;flex-wrap:wrap}.links a{border:1px solid #d8ded8;padding:10px;color:#10211f}</style></head><body><main class="wrap"><a href="/nexustraveltech/admin/">← Panele dön</a><section class="card"><h1>Platform kontrol merkezi</h1><p class="muted">İş kuralları veritabanında tutulur ve kod değiştirmeden yönetilir. API anahtarları şifreli biçimde ayrı sağlayıcı ayarlarında saklanır.</p><?php if($message):?><p class="notice"><?=htmlspecialchars($message)?></p><?php endif;?><?php if($error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post" class="form"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['admin_csrf'])?>"><label>Gemini görsel benzerlik eşiği (%)<input type="number" name="gemini_visual_similarity_threshold" min="50" max="100" value="<?=$threshold?>"></label><label class="toggle"><input type="checkbox" name="gemini_auto_pause_duplicate" <?=$autoPause?'checked':''?>> Gemini yüksek eşleşmede ilanı otomatik duraklatsın</label><label class="toggle"><input type="checkbox" name="kps_identity_verification_enabled" <?=$kpsEnabled?'checked':''?>> KPS kimlik doğrulama entegrasyonu aktif</label><label>Yönetici uyarı e-postası<input type="email" name="admin_alert_email" value="<?=htmlspecialchars($email)?>" placeholder="operasyon@sirketiniz.com"></label><label class="toggle"><input type="checkbox" name="ical_url_published_only" <?=$icalPublishedOnly?'checked':''?>> iCal URL kutusu yalnızca yayındaki ilanlarda gösterilsin (taslaklarda gizli)</label><label>Webhook fiyat varsayılan para birimi<small style="display:block;color:#64716d;font-weight:normal">Kanal yükte <b>currency</b> göndermezse gelen fiyatlar bu birimde kabul edilir; takvimin fiyat planı biriminden farklıysa fx_rates üzerinden çevrilir.</small><input name="channel_webhook_default_currency" maxlength="3" value="<?=htmlspecialchars((string)platform_setting('channel_webhook_default_currency','EUR'))?>" placeholder="EUR"></label><label class="toggle"><input type="checkbox" name="channel_webhook_auto_map" <?=(bool)platform_setting('channel_webhook_auto_map',true)?'checked':''?>> Tanınmayan dış oda kodu gelince onay bekleyen eşleştirme önerisi oluştur <small style="display:block;color:#64716d;font-weight:normal">Açıkken webhook satırı yazılmaz — öneri dağıtım merkezi bölüm 3'te listelenir, onaylanınca o koda ait veriler yazılmaya başlar. Kapalıyken eski davranış: ilk aktif oda tipine yazılır.</small></label><label>Webhook döngü uyarı eşiği (aynı yük son 24 saatte bu kadar kez başarısız olursa tedarikçi + admin uyarısı gönderilir)<input type="number" name="channel_webhook_loop_threshold" min="3" max="100" value="<?=(int)platform_setting('channel_webhook_loop_threshold',3)?>" placeholder="3"></label><label>iCal tekrar hata eşiği (aynı hata içeriği son 24 saatte bu kadar kez tekrarlanırsa tedarikçi + admin uyarısı gönderilir)<input type="number" name="ical_repeat_threshold" min="3" max="100" value="<?=(int)platform_setting('ical_repeat_threshold',3)?>" placeholder="3"></label><label>Webhook maksimum yeniden deneme sayısı (başarısız yükler otomatik kuyruğa geri alınır; geri adım: 1. deneme sonrası 5 dk, 2. sonrası 15 dk)<input type="number" name="channel_webhook_max_retries" min="2" max="10" value="<?=(int)platform_setting('channel_webhook_max_retries',3)?>" placeholder="3"></label><label>Özellik çöp kutusu TTL (gün) — bu süre dolan silinmiş özellikler kalıcı silinir, geri alınamaz (en az 7)<input type="number" name="feature_trash_ttl_days" min="7" max="365" value="<?=(int)platform_setting('feature_trash_ttl_days',30)?>" placeholder="30"></label><label class="toggle"><input type="checkbox" name="readiness_all_auto_open" <?=(bool)platform_setting('readiness_all_auto_open',false)?'checked':''?>> Tesisler kartında "Tüm kalemler" listesi skor düşükken varsayılan açık olsun</label><label>Varsayılan açık eşiği (hazırlık skoru bu değerin altındaysa liste açık gelir)<input type="number" name="readiness_all_auto_open_threshold" min="1" max="100" value="<?=(int)platform_setting('readiness_all_auto_open_threshold',70)?>"></label><label>Yasak kelimeler (ziyaretçi sohbeti; her satıra bir tane, /regex/ biçimi de desteklenir)<textarea name="chat_blocklist" rows="4" style="padding:11px;border:1px solid #d8ded8;font:inherit;font-family:monospace;resize:vertical"><?=htmlspecialchars(implode("\n",(array)platform_setting('chat_blocklist',[])))?></textarea></label><label>Minimum soru uzunluğu (karakter)<input type="number" name="chat_min_length" min="1" max="100" value="<?=(int)platform_setting('chat_min_length',5)?>"></label><label class="toggle"><input type="checkbox" name="chat_require_space" <?=(bool)platform_setting('chat_require_space',true)?'checked':''?>> Tek kelimelik soruları engelle</label><label class="toggle"><input type="checkbox" name="chat_topic_instant" <?=(bool)platform_setting('chat_topic_instant',true)?'checked':''?>> Konuya göre anında yanıtlar aktif (eşleşen konu için tanımlı metin/bağlantı varsa AI çağrısı yapılmaz)</label><div style="display:grid;gap:10px;border:1px dashed #d8ded8;padding:14px;border-radius:8px"><p class="muted" style="margin:0">Konu bazlı karşılama metni ve yönlendirme bağlantısı — metinde <b>{link}</b> yazarsanız yerine mutlak bağlantı konur; bağlantı boşsa eklenmez. İkisi de boşsa o konu için AI yanıtlar.</p><?php $topicResp=(array)platform_setting('chat_topic_responses',[]); foreach(array_keys(chat_topic_defs()) as $t): $r=(array)($topicResp[$t]??[]); ?><label style="border-top:1px solid #eef0ea;padding-top:10px"><b><?=htmlspecialchars($t)?></b><textarea name="chat_topic_responses[<?=htmlspecialchars($t)?>][text]" rows="2" placeholder="Karşılama/yönlendirme metni (boş bırakılırsa AI yanıtlar)" style="width:100%;padding:11px;border:1px solid #d8ded8;font:inherit;font-family:monospace;resize:vertical;margin-top:6px"><?=htmlspecialchars((string)($r['text']??''))?></textarea><input name="chat_topic_responses[<?=htmlspecialchars($t)?>][link]" value="<?=htmlspecialchars((string)($r['link']??''))?>" placeholder="Yönlendirme bağlantısı, örn. /tedarikciler" style="width:100%;padding:11px;border:1px solid #d8ded8;font:inherit;margin-top:6px"></label><?php endforeach; ?></div><button>Kuralları kaydet</button></form></section><section class="card"><h2>Haftalık panel sohbet özeti katılımcıları</h2><p class="muted">Tedarikçi/acente panellerindeki "Her pazartesi haftalık sohbet özetimi e-postama gönder" kutusuyla katılan hesaplar; buradan tek tıkla çıkarabilirsiniz.</p><?php $digest=(array)platform_setting('panel_weekly_digest',[]);$supMap=(array)($digest['supplier']??[]);$agyMap=(array)($digest['agency']??[]);$names=[];if($supMap!==[]){$q=db()->prepare('SELECT id,company_name FROM suppliers WHERE id = ANY(?::bigint[])');$q->execute(['{'.implode(',',array_keys($supMap)).'}']);foreach($q->fetchAll() as $r)$names['supplier_'.$r['id']]=(string)$r['company_name'];}if($agyMap!==[]){$q=db()->prepare('SELECT id,company_name FROM agencies WHERE id = ANY(?::bigint[])');$q->execute(['{'.implode(',',array_keys($agyMap)).'}']);foreach($q->fetchAll() as $r)$names['agency_'.$r['id']]=(string)$r['company_name'];}?><?php if($supMap===[ ]&&$agyMap===[]):?><p class="muted">Henüz katılımcı yok.</p><?php else:?><table style="width:100%;border-collapse:collapse;margin-top:10px"><tr><th style="text-align:left;padding:8px 10px;border-bottom:1px solid #e1e5de;font-size:11px;text-transform:uppercase;color:#64716d">Tip</th><th style="text-align:left;padding:8px 10px;border-bottom:1px solid #e1e5de;font-size:11px;text-transform:uppercase;color:#64716d">Şirket</th><th style="text-align:left;padding:8px 10px;border-bottom:1px solid #e1e5de;font-size:11px;text-transform:uppercase;color:#64716d">E-posta</th><th style="padding:8px 10px;border-bottom:1px solid #e1e5de"></th></tr><?php foreach($supMap as $sid=>$email):?><tr><td style="padding:8px 10px;border-bottom:1px solid #e1e5de">🏨 Tedarikçi</td><td style="padding:8px 10px;border-bottom:1px solid #e1e5de"><b><?=htmlspecialchars($names['supplier_'.$sid]??'#' . $sid)?></b></td><td style="padding:8px 10px;border-bottom:1px solid #e1e5de"><?=htmlspecialchars((string)$email)?></td><td style="padding:8px 10px;border-bottom:1px solid #e1e5de;text-align:right"><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['admin_csrf'])?>"><input type="hidden" name="digest_remove" value="supplier:<?=(int)$sid?>"><button style="background:#8e2410;color:#fff;border:0;padding:6px 12px;font-size:12px;cursor:pointer">Çıkar</button></form></td></tr><?php endforeach;?><?php foreach($agyMap as $aid=>$email):?><tr><td style="padding:8px 10px;border-bottom:1px solid #e1e5de">🧳 Acente</td><td style="padding:8px 10px;border-bottom:1px solid #e1e5de"><b><?=htmlspecialchars($names['agency_'.$aid]??'#' . $aid)?></b></td><td style="padding:8px 10px;border-bottom:1px solid #e1e5de"><?=htmlspecialchars((string)$email)?></td><td style="padding:8px 10px;border-bottom:1px solid #e1e5de;text-align:right"><form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['admin_csrf'])?>"><input type="hidden" name="digest_remove" value="agency:<?=(int)$aid?>"><button style="background:#8e2410;color:#fff;border:0;padding:6px 12px;font-size:12px;cursor:pointer">Çıkar</button></form></td></tr><?php endforeach;?></table><?php endif;?></section><section class="card"><h2>🔔 Webhook döngü durumu</h2><?php
$webhookDefault=max(3,(int)platform_setting('channel_webhook_loop_threshold',3));
$hasCol=(bool)db()->query("SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='channel_connections' AND column_name='webhook_loop_threshold'")->fetchColumn();
$connOverrides=$hasCol?(int)db()->query('SELECT COUNT(*) FROM channel_connections WHERE webhook_loop_threshold IS NOT NULL')->fetchColumn():0;
$over=[];try{
if($hasCol){$overSql="SELECT c.display_name,c.channel_code,s.company_name,c.webhook_loop_threshold,COUNT(*) attempt_count,MIN(l.created_at) first_at,MAX(l.created_at) last_at FROM channel_sync_logs l JOIN channel_connections c ON c.id=l.channel_connection_id JOIN suppliers s ON s.id=c.supplier_id WHERE l.direction='pull' AND l.status='failed' AND l.created_at>=now()-interval '24 hours' AND l.request_payload IS NOT NULL GROUP BY c.id,md5(l.request_payload::text),c.display_name,c.channel_code,s.company_name,c.webhook_loop_threshold HAVING COUNT(*)>=COALESCE(c.webhook_loop_threshold,{$webhookDefault}) ORDER BY attempt_count DESC LIMIT 15";}else{$overSql="SELECT c.display_name,c.channel_code,s.company_name,COUNT(*) attempt_count,MIN(l.created_at) first_at,MAX(l.created_at) last_at FROM channel_sync_logs l JOIN channel_connections c ON c.id=l.channel_connection_id JOIN suppliers s ON s.id=c.supplier_id WHERE l.direction='pull' AND l.status='failed' AND l.created_at>=now()-interval '24 hours' AND l.request_payload IS NOT NULL GROUP BY c.id,md5(l.request_payload::text),c.display_name,c.channel_code,s.company_name HAVING COUNT(*)>={$webhookDefault} ORDER BY attempt_count DESC LIMIT 15";}
$over=db()->query($overSql)->fetchAll();}catch(Throwable $e){$over=[];}
$alerts=[];try{$alerts=db()->query("SELECT n.type,n.message,n.created_at,c.display_name,s.company_name FROM notifications n JOIN channel_connections c ON c.id=(regexp_split_to_array(n.type,'_'))[3]::bigint LEFT JOIN suppliers s ON s.id=c.supplier_id WHERE n.type LIKE 'webhook_loop_%' ORDER BY n.created_at DESC LIMIT 10")->fetchAll();}catch(Throwable $e){$alerts=[];}
?><p class="muted">Aynı webhook yükü son 24 saatte başarısız olmaya devam ederse tedarikçiye panel bildirimi + yöneticiye e-posta gider. Varsayılan eşik <b><?=$webhookDefault?></b>; kanal bazlı geçersiz kılmalar: <b><?=$connOverrides?> bağlantı</b> (dağıtım merkezi bölüm 1'den düzenlenir).</p><h3 style="margin:14px 0 6px;font-size:14px">⚠ Şu an eşiği aşan bağlantılar (son 24 saat)</h3><?php if(!$over):?><p class="muted" style="color:#405b13">✓ Son 24 saatte eşiği aşan bağlantı yok.</p><?php else:?><table style="width:100%;border-collapse:collapse;font-size:13px"><?php foreach($over as $o):?><tr><td style="padding:7px 10px;border:1px solid #e1e5de"><b><?=htmlspecialchars($o['display_name'])?></b> (<?=htmlspecialchars($o['channel_code'])?>) · <?=htmlspecialchars($o['company_name'])?></td><td style="padding:7px 10px;border:1px solid #e1e5de;color:#b0301a"><b><?=(int)$o['attempt_count']?> kez</b></td><td style="padding:7px 10px;border:1px solid #e1e5de">eşik: <?=$hasCol&&$o['webhook_loop_threshold']!==null?(int)$o['webhook_loop_threshold']:'varsayılan '.$webhookDefault?></td><td style="padding:7px 10px;border:1px solid #e1e5de;color:#64716d"><?=htmlspecialchars((string)$o['first_at'])?> → <?=htmlspecialchars((string)$o['last_at'])?></td></tr><?php endforeach;?></table><?php endif;?><h3 style="margin:16px 0 6px;font-size:14px">🔔 Son tetiklenen döngü uyarıları</h3><?php if(!$alerts):?><p class="muted">Henüz döngü uyarısı tetiklenmedi.</p><?php else:?><?php foreach($alerts as $a):?><p style="margin:0 0 8px;padding:8px 10px;background:#fff8f0;border:1px solid #f3d9b8;border-radius:6px;font-size:13px"><b><?=htmlspecialchars($a['display_name']??'#kanal')?></b> · <?=htmlspecialchars((string)$a['created_at'])?><br><?=htmlspecialchars(mb_substr((string)$a['message'],0,160))?></p><?php endforeach;?><?php endif;?></section><section class="card"><h2>Şifreli API ayarları</h2><div class="links"><a href="/nexustraveltech/admin/ai-ayarlari">DeepSeek metin AI</a><a href="/nexustraveltech/admin/gemini-ayarlari">Gemini görsel AI</a><a href="/nexustraveltech/admin/tedarikci-onaylari">Tedarikçi onayları</a><a href="/nexustraveltech/admin/ozellik-listeleri">Katalog & sınıflandırma yönetimi</a></div></section></main><?php require_once __DIR__.'/../config/ai_widget.php'; ai_widget('/nexustraveltech/admin/ai-chat','admin_csrf'); ?></body></html>
